# Every generated file starts with this; regeneration deletes only files that do
MARKER = "# Generated by apiroute"

_LINE_LENGTH = 100


def generated_header(version: str, source: str) -> str:
    """The first line(s) of a generated file. "Do not edit" moves to a line of its own when
    one line would be longer than generated code may be (a GraphQL source names two paths)."""
    origin = f"{MARKER} {version} from {source}."
    line = f"{origin} Do not edit: regenerate instead."
    if len(line) <= _LINE_LENGTH:
        return line
    return f"{origin}\n# Do not edit: regenerate instead."
